<template>\n  <div class=\"tree-node\" :class=\"{ 'is-leaf': !node.children || node.children.length === 0 }\">\n    <!-- Node Label/Word -->\n    <div class=\"node-wrapper\" @mouseenter=\"showTooltip = true\" @mouseleave=\"showTooltip = false\">\n      <div class=\"node-label\" :class=\"{ 'is-word': isWord }\">\n        {{ node.label }}\n      </div>\n\n      <!-- Tooltip -->\n      <div v-if=\"showTooltip && (node.meaning || node.pos)\" class=\"tooltip\">\n        <div v-if=\"node.pos\" class=\"tooltip-row\">\n          <strong>POS:</strong> {{ node.pos }}\n        </div>\n        <div v-if=\"node.meaning\" class=\"tooltip-row\">\n          <strong>Meaning:</strong> {{ node.meaning }}\n        </div>\n      </div>\n\n      <!-- Audio Button -->\n      <button\n        v-if=\"node.audio\"\n        class=\"audio-btn\"\n        @click=\"playAudio\"\n        :title=\"`Pronounce: ${node.label}`\"\n      >\n        🔊\n      </button>\n    </div>\n\n    <!-- Children -->\n    <div v-if=\"node.children && node.children.length > 0\" class=\"children-container\">\n      <div class=\"connector-line\" :style=\"{ height: connectorHeight }\"></div>\n      <div class=\"children\">\n        <ParseTreeNode\n          v-for=\"(child, idx) in node.children\"\n          :key=\"idx\"\n          :node=\"child\"\n          :depth=\"depth + 1\"\n        />\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, computed } from 'vue'\n\ninterface TreeNode {\n  label: string\n  meaning?: string\n  pos?: string\n  audio?: string\n  children?: TreeNode[]\n}\n\nconst props = defineProps<{\n  node: TreeNode\n  depth: number\n}>()\n\nconst showTooltip = ref(false)\n\nconst isWord = computed(() => {\n  return !props.node.children || props.node.children.length === 0\n})\n\nconst connectorHeight = computed(() => {\n  if (!props.node.children || props.node.children.length === 0) return '0'\n  // Rough estimate based on depth\n  return `${30 + props.depth * 10}px`\n})\n\nconst playAudio = async () => {\n  if (!props.node.audio) return\n  \n  try {\n    const audio = new Audio(props.node.audio)\n    await audio.play()\n  } catch (error) {\n    console.error('Audio play error:', error)\n  }\n}\n</script>\n\n<style scoped>\n.tree-node {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  margin: 1rem;\n}\n\n.node-wrapper {\n  position: relative;\n  display: inline-block;\n}\n\n.node-label {\n  padding: 0.75rem 1.5rem;\n  background-color: #e8f4f8;\n  border: 2px solid #0066cc;\n  border-radius: 6px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: all 0.3s ease;\n  text-align: center;\n  min-width: 80px;\n}\n\n.node-label:hover {\n  background-color: #d0e8f2;\n  border-color: #0052a3;\n  transform: scale(1.05);\n}\n\n.node-label.is-word {\n  background-color: #fff3cd;\n  border-color: #ff9800;\n}\n\n.node-label.is-word:hover {\n  background-color: #ffe8a1;\n  border-color: #e68900;\n}\n\n.tooltip {\n  position: absolute;\n  bottom: calc(100% + 10px);\n  left: 50%;\n  transform: translateX(-50%);\n  background-color: #333333;\n  color: #ffffff;\n  padding: 0.75rem 1rem;\n  border-radius: 4px;\n  font-size: 0.875rem;\n  white-space: nowrap;\n  z-index: 10;\n  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);\n}\n\n.tooltip::after {\n  content: '';\n  position: absolute;\n  top: 100%;\n  left: 50%;\n  transform: translateX(-50%);\n  border: 5px solid transparent;\n  border-top-color: #333333;\n}\n\n.tooltip-row {\n  margin: 0.25rem 0;\n}\n\n.tooltip-row:first-child {\n  margin-top: 0;\n}\n\n.tooltip-row:last-child {\n  margin-bottom: 0;\n}\n\n.audio-btn {\n  position: absolute;\n  top: -8px;\n  right: -8px;\n  background-color: #4caf50;\n  color: white;\n  border: none;\n  border-radius: 50%;\n  width: 28px;\n  height: 28px;\n  padding: 0;\n  cursor: pointer;\n  font-size: 1rem;\n  transition: all 0.3s ease;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.audio-btn:hover {\n  background-color: #45a049;\n  transform: scale(1.1);\n}\n\n.children-container {\n  position: relative;\n  margin-top: 1.5rem;\n}\n\n.connector-line {\n  position: absolute;\n  left: 50%;\n  top: -1.5rem;\n  transform: translateX(-50%);\n  width: 2px;\n  background-color: #cccccc;\n}\n\n.children {\n  display: flex;\n  justify-content: center;\n  gap: 0.5rem;\n  flex-wrap: wrap;\n}\n\n.is-leaf .node-label {\n  min-width: auto;\n}\n\n@media (max-width: 640px) {\n  .node-label {\n    padding: 0.5rem 1rem;\n    font-size: 0.875rem;\n    min-width: 60px;\n  }\n\n  .tooltip {\n    font-size: 0.75rem;\n    padding: 0.5rem 0.75rem;\n  }\n}\n</style>